class RecoveryMetadataError(BridgeError):
    """Invalid recovery explanation; no Session authority has been consulted."""

    code = "invalid_arguments"


_RECOVERY_METADATA_UNSET = object()


def normalize_resume_metadata(
    note: Any = _RECOVERY_METADATA_UNSET,
    reason: Any = _RECOVERY_METADATA_UNSET,
) -> str:
    """Accept the published explanation alias before any recovery mutation."""
    guidance = (
        "visionstudio_confirm_resume_stage requires arguments "
        "{session_id: <current session_id>, stage_id: <current stage_id>, "
        "matched_state: observe|success, note: <non-blank string, 1..500 characters>}. "
        "The published reason alias may replace note; if both are supplied "
        "their trimmed text must match. No recovery state was changed."
    )
    values = []
    for value in (note, reason):
        if value is _RECOVERY_METADATA_UNSET:
            continue
        if not isinstance(value, str) or not value.strip() or len(value) > 500:
            raise RecoveryMetadataError(guidance)
        values.append(value.strip())
    if not values or any(value != values[0] for value in values[1:]):
        raise RecoveryMetadataError(guidance)
    return values[0]

